import {selectNegativeReviews,negativeFingerprints,HUMAN_RUBRIC,NEGATIVE_ESTABLISHMENT,NEGATIVE_NAME,NEGATIVE_METHOD,HUMAN_RUBRIC_VERSION,type NegativeCandidate,type NegativeRun,type NegativeLabel} from '../../supabase/functions/_shared/negative-validation-core'
import {NEGATIVE_MODEL_CONFIG,type NegativeTask} from '../../supabase/functions/_shared/negative-validation-score'
import {THEME_KEYS,type ThemeDecision} from '../../supabase/functions/_shared/jev-themes'
export const negativeUuid=(i:number)=>'00000000-0000-4000-8000-'+String(i).padStart(12,'0')
export function syntheticNegativeCandidates(english=true):NegativeCandidate[]{return Array.from({length:80},(_,i)=>({id:negativeUuid(i+1),rating:i<40?i%3+1:i<60?4:5,original_text:i===79?'':`ORIGINAL_PRIVATE_SENTINEL ${i}`,original_language:english?'ru':'vi',published_at:'2026-01-01T00:00:00Z',review_detailed_rating:{Food:5,Service:2,Atmosphere:4},review_translations:english?[{language:'en',translated_text:`The food was cold and we waited a long time. English synthetic ${i}.`}]:[{language:'fr',translated_text:'French is not English'}]}))}
export async function syntheticNegative(){const live=syntheticNegativeCandidates(),selection=await selectNegativeReviews(live),run:NegativeRun={id:negativeUuid(900),organization_id:negativeUuid(901),establishment_id:NEGATIVE_ESTABLISHMENT,name:NEGATIVE_NAME,methodology:NEGATIVE_METHOD,status:'draft',revision:0,benchmark_status:'idle',rubric:HUMAN_RUBRIC,rubric_version:HUMAN_RUBRIC_VERSION,selection_pool:selection.pool,reference_at:'2026-10-08T00:00:00Z',created_at:'2026-10-08T00:00:00Z',created_by:negativeUuid(902),human_completed_at:null,dataset_fingerprint:null,label_fingerprint:null,benchmark_started_at:null,benchmark_completed_at:null,benchmark_error:null,rates:{jev_input:.042}};return {live,run,items:selection.items}}
export async function completeNegative(h:Awaited<ReturnType<typeof syntheticNegative>>){const labels:NegativeLabel[]=h.items.flatMap(i=>THEME_KEYS.map(theme_key=>({review_id:i.review_id,theme_key,choice:theme_key==='temperature'||theme_key==='wait_time'?'negative' as const:'absent' as const})));h.items.forEach(i=>i.confirmed_at='2026-10-08T00:01:00Z');h.run.status='completed';h.run.human_completed_at='2026-10-08T00:01:00Z';Object.assign(h.run,await negativeFingerprints(h.items,labels));return labels}
export function negativeDecision(negativeKeys:string[]):ThemeDecision{return {themes:Object.fromEntries(THEME_KEYS.map(k=>[k,{choice:negativeKeys.includes(k)?'negative':'absent',probabilities:{absent:negativeKeys.includes(k)?0:1,positive:0,negative:negativeKeys.includes(k)?1:0,both:0}}])) as ThemeDecision['themes']}}
export function syntheticNegativeTasks(h:Awaited<ReturnType<typeof syntheticNegative>>):NegativeTask[]{return h.items.flatMap((i,n)=>(['v9','v11'] as const).flatMap(model_version=>[1,2,3].map(repeat=>({id:negativeUuid(1000+n*6+(model_version==='v9'?0:3)+repeat),experiment_id:h.run.id,model_version,review_id:i.review_id,review_alias:'r'+i.position,question_set_version:NEGATIVE_MODEL_CONFIG[model_version].question_set,repeat,status:'completed' as const,response:negativeDecision(model_version==='v9'?['temperature']:['temperature','wait_time']),served_model:'jev-fixture',input_tokens:100,output_tokens:10,request_count:1,retry_count:0,cost_usd:.0000042,duration_ms:100,error_code:null,usage_complete:true}))))}
